    MonarchTemplatePickerItem(id: {{templates.1.id}}, name: {{templates.1.name}}, description: {{templates.1.description}}, category: {{templates.1.category}}, image: Self.thumbnail({{templates.1.id}}, dark: scheme == .dark)),
